import os, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    if not os.path.exists(path):
        return {}
    text = open(path).read().replace('\\n', '\n')

    G = {}
    pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
    for m in pattern.finditer(text):
        k, h, w = m[1], int(m[2]), int(m[3])
        snippet = text[m.end():].split('\n')[k]  # Get the right number of rows

        # Parse rows - looking for numeric grids
        lines = []
        rest = text[m.end():]
        new_mend = m.end()
        while len(lines) < h:
            newline_pos = rest.find('\n', new_mend)
            if newline_pos == -1:
                break
            lines.append(rest[new_mend:newline_pos])
            new_mend = newline_pos + 1
        if len(lines) >= h:
            lines = lines[:h]

        valid_rows = [r for r in lines if len(r) > 0 and r.split()[0].isdigit()]
        if len(valid_rows) >= h:
            grid = [[int(x) for x in row.split()] for row in valid_rows[:h]]
            if all(len(row) == w for row in grid):
                G[k] = grid
                break

    return G

